\vspace{0.3cm}

\noindent
Answer question ONE and any other TWO questions

\vspace{0.5cm}

\begin{enumerate}
 \item 
 \begin{enumerate}
 \item[(a)] Explain any four conditions that led to the developments of Sociology as a discipline 
 \item[(b)] With examples, describe how university students can benefit from the sociological imagination (10 marks)
 \end{enumerate}

 \item 
 \begin{enumerate}
 \item[(a)] using a higher education institution as an illustrative example, explain the meaning of social structure (15 marks)
 \item[(b)] Highlight components of a social structure (5 marks)
 \end{enumerate}

 \item 
 \begin{enumerate}
 \item[(a)] What is social organisation? (5 marks)
 \item[(b)] With examples, describe the five forms of social organisation (15 marks)
 \end{enumerate}

 \item Describe the contributions of any \textbf{THREE} founding thinkers of Sociology. (20 Marks)

 \item Explain the following sociological concepts
 \begin{enumerate}
 \item[(a)] Role conflict
 \item[(b)] Social determination
 \item[(c)] Social deviance
 \item[(d)] Looking-glass self
 \item[(e)] Revolution
 \end{enumerate}
\end{enumerate}

\vspace{0.5cm}
\hrule
