\begin{enumerate}
 \item 
 \begin{enumerate}
 \item[(i)] Explain Anthropology, and trace its development. (10 marks)
 \item[(ii)] Describe any \textbf{Three} Anthropological schools of thought. (20 marks)
 \end{enumerate}

 \vspace{0.3cm}

 \item 
 \begin{enumerate}
 \item[(i)] Describe social structure, and explain its basic components. (10 marks)
 \item[(ii)] Discuss controversies in contemporary society regarding the use of gender in the allocation of status. (10 marks)
 \end{enumerate}

 \vspace{0.3cm}

 \item Citing examples, discuss the role of culture in the development of the individual and society. (20 marks)

 \vspace{0.3cm}

 \item Explain the challenges of child rearing in modern society and discuss the problems affecting marriage in an urban society. (20 marks)

 \vspace{0.3cm}

 \item Describe \textbf{three} research approaches used in Anthropology, and discuss their importance. (20 marks)
\end{enumerate}

